-- 声纹权限：按 big-herdsman 固件实际上报的 MCP 工具名（self.production.* → self_production_*）重写预置权限项。
-- 读类工具统一以 _get / _get_xxx 结尾，写类以 _set / _open / _close / _start / _stop 结尾，按动词拆成「查询」与各类「控制」权限。
-- 单独建 changeSet 而不改 202611222200.sql：已执行过的 changelog 改动会导致 Liquibase 校验和失败。

UPDATE `sys_params` SET param_value = '[{"code":"chat","name":"闲聊","tools":["get_weather","get_lunar","get_news*","web_search","play_music","change_role"]},{"code":"device_admin","name":"设备维护(改地址)","tools":["self_production_device_address_set"]},{"code":"production_read","name":"查生产设备信息","tools":["self_production_*_get","self_production_*_get_*"]},{"code":"light_control","name":"控制灯光","tools":["self_production_light*_open","self_production_light*_close","self_production_lights_set_all","self_production_light_schedule_set"]},{"code":"water_control","name":"控制水线/加药/冲洗","tools":["self_production_main_water_valve_set","self_production_dosing_set","self_production_flush_*"]},{"code":"feed_control","name":"控制喂料","tools":["self_production_feed_cart_start*","self_production_feed_line*_set"]},{"code":"alarm_control","name":"报警与死淘登记","tools":["self_production_alarm_pause_set","self_production_daily_mortality_set"]},{"code":"knowledge_base","name":"查知识库","tools":["search_from_ragflow","*knowledge*"]},{"code":"device_read","name":"查板子自身状态","tools":["self_*get*","self_*status*"]},{"code":"device_control","name":"控制板子自身(音量/屏幕等)","tools":["self_*","hass_*","call_device"]}]' WHERE param_code = 'server.voiceprint_permission_items';

UPDATE `sys_params` SET param_value = 'chat,production_read' WHERE param_code = 'server.voiceprint_permission_default';
